from research_helpers import *
A=ev('https://www.sec.gov/Archives/edgar/data/831547/000083154723000007/sppi-20221231.htm','Spectrum2022 issuer identifies Rolvedon/eflapegrastim and licensed poziotinib; FDA CRL and development deprioritization, not approval.')
B=ev('https://www.sec.gov/Archives/edgar/data/1808665/000180866526000019/asrt-20260331.htm','2026 parent confirms Rolvedon marketed product; intra-group commercialization integrated intoAssertioSpecialty2025. OtherAssertio products not automatically attributed toSpectrum.')
D=ev('https://www.sec.gov/Archives/edgar/data/831547/000083154719000010/a8-kacrotechtransaction.htm','Completed sale of seven commercial drugs toAcrotech onMarch1 2019; historical commercial relationship ends on that date.')
N=ev('https://www.sec.gov/Archives/edgar/data/831547/000083154719000005/exhibit991q42018.htm','Issuer2018 results identify seven divested product generic identities.')
O=ev('https://www.sec.gov/Archives/edgar/data/831547/000119312512342377/d381778dex991.htm','Historical issuer names apaziquone,SPI1620,lucanthone andRenaZorb/SPI014. Old clinical milestones do not establish current development.')
ps=[p('ROLVEDON','Eflapegrastim-xnst injection for chemotherapy-associated neutropenia.',A,'commercial',aliases=['eflapegrastim','ROLONTIS'],roles=['developer'],typ='product',evidence=[A,B],attributes={'company_relationship':'Historical Spectrum co-development; parent reports commercial integration into Assertio Specialty in 2025.'}),p('Poziotinib','Historical licensed pan-HER inhibitor oncology candidate; FDA CRL in2022 and development deprioritized.',A,roles=['licensee'],territory='worldwide excluding Korea and China')]
for name,generic in [('FUSILEV','Levoleucovorin for injection.'),('KHAPZORY','Levoleucovorin for injection; distinct branded formulation.'),('FOLOTYN','Pralatrexate injection.'),('ZEVALIN','Ibritumomab tiuxetan radiotherapy product.'),('MARQIBO','Liposomal vincristine sulfate injection.'),('BELEODAQ','Belinostat for injection.'),('EVOMELA','Melphalan for injection.')]:ps.append(p(name,generic,D,roles=['commercial_partner'],typ='product',valid_to='2019-03-01',evidence=[D,N],attributes={'historical_relationship_ended':'2019-03-01','buyer':'Acrotech Biopharma','current_product_availability':'not established by reviewed historical sale evidence'}))
for n,d,a in [('Apaziquone','Historical bladder cancer drug candidate.',[]),('SPI-1620','Historical oncology development candidate.',[]),('Lucanthone','Historical glioblastoma development candidate.',[]),('RenaZorb','Historical phosphate-binding development candidate.',['SPI-014'])]:ps.append(p(n,d,O,aliases=a))
cs=[company('Spectrum Pharmaceuticals Inc',ps,[A,B,D,N,O],'13 current and historical assets reviewed, seven commercial relationship end dates from completed2019 sale. Rolvedon co-development distinguished from2025parentcommercial integration; unrelatedAssertio assets excluded. Full historical pipeline, subsequent rights disposition and RenaZorb successor identity/current status require followup.')]
(out/'batch-0073.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
